 // Dynamically set the corresponding service\n        if (this.initialData()?.isAdmin) {\n            this.form.controls['oldPassword'].removeValidators(Validators.required);\n            this.createService = (payload: any) => this.#usersService.resetUserPassword({userId: this.initialData()?.user.id as string, password: payload});\n        } else {\n            this.createService = (payload: any) => this.#usersService.updateUserPassword({userId: this.initialData()?.user.id as string, userPasswordReset: payload});\n        }\n        this.updateService = () => {null}; \n    }\n\n\n    readonly payload = (): UserPasswordReset | string => {\n        const data = this.form.value;    \n        if (this.initialData()?.isAdmin) {\n            return data.newPassword as string\n        } else {\n            return {\n                oldPassword: data.oldPassword,\n                newPassword: data.newPassword,\n            } as UserPasswordReset;\n        }\n    }\n\n}\n    \n\n\n\n    \n        \n        \n            \n                Legend\n            \n            \n                Html element\n            \n            \n                Component\n            \n            \n                Html element with directive\n            \n        \n    \n\n    \n\n\n\n\n\n\n        var COMPONENT_TEMPLATE = '                      @if (!initialData()?.isAdmin) {                            Old Password                                                    }                    New Password                                                    Confirm the new password                                            '\n    var COMPONENTS = [{'name': 'AbstractFormBase', 'selector': ''},{'name': 'AdverseEventEventComponent', 'selector': 'onconova-adverse-event-event'},{'name': 'AdverseEventFormComponent', 'selector': 'adverse-event-form'},{'name': 'AppComponent', 'selector': 'onconova-root'},{'name': 'AppFooterComponent', 'selector': 'onconova-footer'},{'name': 'AppLayoutComponent', 'selec